                    for step in range(sz - 1):
                        if colors[(start + step) % n] == colors[(start + step + 1) % n]:
                            valid = False
                            break
                    if valid:
                        count += 1
                ans.append(count)
            else:
                colors[q[1]] = q[2]
        return ans
