class Solution {
public:
    vector<int> numberOfAlternatingGroups(vector<int>& colors, vector<vector<int>>& queries) {
        int n = colors.size();
        vector<int> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                int sz = q[1];
                int count = 0;
                for (int start = 0; start < n; ++start) {
                    bool valid = true;
                    for (int step = 0; step < sz - 1; ++step) {
                        if (colors[(start + step) % n] == colors[(start + step + 1) % n]) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) count++;
                }
                ans.push_back(count);
            } else {
                colors[q[1]] = q[2];
            }
        }
        return ans;
    }
};

